#### P5250 【深基 17.例 5】木材仓库
```cpp
int main() {
	int operation, length, rounds;
	cin >> rounds;
	set<int> wood;
	for(int i = 0; i < rounds; i++) {
		cin >> operation >> length;
		if(operation == 1 && wood.contains(length)) {
			cout << "Already Exist\n";
		} else if(operation == 1 && !wood.contains(length)) {
			wood.insert(length);
		} else if(operation == 2 && wood.empty()) {
			cout << "Empty\n";
		} else if(operation == 2 && wood.contains(length)) {
			cout << length << '\n';
			wood.erase(length);
		} else if(operation == 2 && !wood.contains(length) && !wood.empty()) {
			auto bigger = wood.upper_bound(length);
			if(bigger == wood.begin()) {
				cout << *bigger << '\n';
				wood.erase(bigger);
			} else if(bigger == wood.end()) {
				// int smaller = *wood.rbegin();
				// cout << smaller << '\n';
				// wood.erase(smaller);
				auto smaller = prev(wood.end());
				cout << *smaller << '\n';
				wood.erase(smaller);
			} else {
				auto smaller = std::prev(bigger);
				if((*bigger - length) >= (length - *smaller)) {
					cout << *smaller << '\n';
					wood.erase(smaller);
				} else {
					cout << *bigger << '\n';
					wood.erase(bigger);
				}
			}
		}
	}
	return 0;
}
```
- 注意注释位置，`erase()` 中如果**传入的不是迭代器而是函数，会导致容器中所有相同的数被删除**，这可能会导致难以察觉的 bug
- `erase()` 函数不接受反向迭代器

